// C2PAStatus — Summary validation status of a C2PA content credentials manifest.
//
// Populated by the Exchange or a C2PA verification vendor after validating
// the manifest against the C2PA specification (§15 Validation Algorithm).
// Maps to C2PA's three validation states: well-formed, valid, trusted.
//
// Trust is determined by the C2PA Trust List (curated X.509 roots).
// RAMP bridges this trust via ResourceAttestation: a RAMP-trusted
// verification vendor validates the C2PA manifest and publishes
// the results as attestation claims signed with Ed25519.
type C2PAStatus int32

const (
	C2PAStatus_C2PA_STATUS_UNSPECIFIED C2PAStatus = 0 // unset — rejected at ingest
	// Manifest is valid AND signer certificate chains to a C2PA Trust List root.
	// Highest assurance: provenance is cryptographically verified by a trusted CA.
	C2PAStatus_C2PA_STATUS_TRUSTED C2PAStatus = 1
	// Manifest is structurally correct and signature verifies, but signer
	// certificate does NOT chain to a C2PA Trust List root. The content
	// has provenance, but the signer is not institutionally vouched for.
	C2PAStatus_C2PA_STATUS_VALID C2PAStatus = 2
	// Manifest is present but validation failed (signature mismatch,
	// malformed JUMBF, certificate expired, hard binding broken).
	C2PAStatus_C2PA_STATUS_INVALID C2PAStatus = 3
	// Content was checked and has no C2PA manifest.
	C2PAStatus_C2PA_STATUS_ABSENT C2PAStatus = 4
)

