// DisputeStatus — Lifecycle state of a resource dispute.
//
// Disputes progress through a three-tier resolution process:
//
//	Tier 1 (automated, <1 second, ~99% of cases): Auto-credit when evidence
//	  is independently verifiable (CDN logs, cryptographic hash comparison).
//	  FILED → AUTO_RESOLVED.
//	Tier 2 (rule-based review, <24 hours, ~0.9%): Exchange applies concrete
//	  resolution rules when Tier 1 evidence is inconclusive.
//	  FILED → EVIDENCE_NEEDED → UNDER_REVIEW → RESOLVED.
//	Tier 3 (pattern investigation, async, ~0.1%): Triggered by aggregate
//	  patterns (e.g., agent dispute rate >5%, provider token discrepancy >2%).
//	  ESCALATED → SETTLED → FINAL.
//
// Appeals: losing party may appeal with new evidence.
//
//	RESOLVED → APPEALED → UNDER_REVIEW (re-enters Tier 2).
type DisputeStatus int32

const (
	DisputeStatus_DISPUTE_STATUS_UNSPECIFIED DisputeStatus = 0 // unset — rejected at ingest
	// Agent submitted DisputeRequest. Initial state.
	DisputeStatus_DISPUTE_STATUS_FILED DisputeStatus = 1
	// Exchange auto-resolved via Tier 1 rules (CDN logs, hash comparison).
	DisputeStatus_DISPUTE_STATUS_AUTO_RESOLVED DisputeStatus = 2
	// Exchange requests additional evidence from the agent or provider.
	DisputeStatus_DISPUTE_STATUS_EVIDENCE_NEEDED DisputeStatus = 3
	// Exchange is reviewing with Tier 2 resolution rules.
	DisputeStatus_DISPUTE_STATUS_UNDER_REVIEW DisputeStatus = 4
	// Escalated to Tier 3 pattern-based investigation.
	DisputeStatus_DISPUTE_STATUS_ESCALATED DisputeStatus = 5
	// Decision made (credit, redelivery, rejected). See resolution field.
	DisputeStatus_DISPUTE_STATUS_RESOLVED DisputeStatus = 6
	// Losing party appealed with new evidence. Re-enters review.
	DisputeStatus_DISPUTE_STATUS_APPEALED DisputeStatus = 7
	// Financial settlement applied.
	DisputeStatus_DISPUTE_STATUS_SETTLED DisputeStatus = 8
	// No further appeals. Dispute closed.
	DisputeStatus_DISPUTE_STATUS_FINAL DisputeStatus = 9
)

